    $g = $conn->prepare("SELECT slug, verify_mode, secret_header FROM custom_webhooks WHERE id = ? LIMIT 1");
    $g->bind_param('i', $id); $g->execute(); $gr = $g->get_result();
    $row = $gr ? $gr->fetch_assoc() : null; $g->close();
