// Send a signed test through the real public endpoint so it exercises verification,
// routing and the WebSocket hop exactly like an external sender would.
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['test_webhook'])) {
    $id = (int) ($_POST['webhook_id'] ?? 0);
    if ($id <= 0) wh_json(['success' => false, 'message' => t('admin_webhooks_err_not_found')]);
    $g = $conn->prepare("SELECT slug, service, scope, verify_mode, secret, secret_header, enabled FROM custom_webhooks WHERE id = ? LIMIT 1");
    $g->bind_param('i', $id); $g->execute(); $gr = $g->get_result();
    $row = $gr ? $gr->fetch_assoc() : null; $g->close();
    if (!$row) wh_json(['success' => false, 'message' => t('admin_webhooks_err_not_found')]);
    if (!(int) $row['enabled']) wh_json(['success' => false, 'message' => t('admin_webhooks_err_test_disabled')]);
    // Webhooks created before keys were auto-provisioned may have no usable service key.
    $keyNote = wh_key_note(wh_ensure_service_key($conn, $row['service'], $row['scope']), $row['service']);
    $body = json_encode([
        'type' => 'test',
        'data' => ['status' => 'test', 'message' => 'BotOfTheSpecter webhook test'],
        'sent_by' => $_SESSION['username'] ?? '',
        'sent_at' => gmdate('c'),
    ]);
    $headers = ['Content-Type: application/json'];
    if ($row['verify_mode'] !== 'none') {
        $headerName = $row['secret_header'] !== '' ? $row['secret_header'] : wh_default_header($row['verify_mode']);
        $secret = (string) $row['secret'];
        if ($row['verify_mode'] === 'hmac' && (strpos($secret, 'whsec_') === 0 || strtolower($headerName) === 'webhook-signature')) {
            // Standard Webhooks (OpenAI): three headers, signature over "{id}.{timestamp}.{body}"
            $msgId = 'msg_test_' . bin2hex(random_bytes(8));
            $ts = time();
            $key = base64_decode(strpos($secret, 'whsec_') === 0 ? substr($secret, 6) : $secret, true);
            $headers[] = 'webhook-id: ' . $msgId;
            $headers[] = 'webhook-timestamp: ' . $ts;
            $headerName = 'webhook-signature';
            $value = 'v1,' . base64_encode(hash_hmac('sha256', $msgId . '.' . $ts . '.' . $body, $key === false ? '' : $key, true));
        } elseif ($row['verify_mode'] === 'hmac') {
            if (strtolower($headerName) === 'elevenlabs-signature') {
                $ts = time();
                $value = 't=' . $ts . ',v0=' . hash_hmac('sha256', $ts . '.' . $body, $secret);
            } else {
                $value = hash_hmac('sha256', $body, $secret);
            }
        } else {
            $value = $secret;
        }
        $headers[] = $headerName . ': ' . $value;
    }
    $ch = curl_init($apiBase . '/webhook/' . rawurlencode($row['slug']));
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => $body,
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 20,
    ]);
    $response = curl_exec($ch);
    $httpCode = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $curlError = curl_error($ch);
    curl_close($ch);
    admin_audit_log('custom_webhook_test', $httpCode === 200 ? 'success' : 'warning', ['slug' => $row['slug'], 'http' => $httpCode], 'custom_webhook', $row['slug']);
    if ($response === false) {
        wh_json(['success' => false, 'message' => t('admin_webhooks_err_test_unreachable', [$curlError])]);
    }
    $decoded = json_decode($response, true);
    if ($httpCode === 200) {
        wh_json(['success' => true, 'message' => t('admin_webhooks_msg_test_ok', [(int) ($decoded['delivered'] ?? 0)]) . $keyNote]);
    }
    $detail = is_array($decoded) && isset($decoded['detail']) && is_string($decoded['detail']) ? $decoded['detail'] : substr((string) $response, 0, 200);
    wh_json(['success' => false, 'message' => t('admin_webhooks_err_test_failed', [$httpCode, $detail]) . $keyNote]);
}

// Map a stored delivery status to its translated label (unknown codes are shown as-is)
function wh_status_label($status) {
    $keys = [
        'ok' => 'admin_webhooks_status_ok',
        'no_admin_key' => 'admin_webhooks_status_no_admin_key',
        'key_not_marked' => 'admin_webhooks_status_key_not_marked',
        'no_target' => 'admin_webhooks_status_no_target',
        'channel_not_registered' => 'admin_webhooks_status_channel_not_registered',
        'no_listeners' => 'admin_webhooks_status_no_listeners',
        'forward_failed' => 'admin_webhooks_status_forward_failed',
    ];
    return isset($keys[$status]) ? t($keys[$status]) : $status;
}

// ---- beta admin tail (scripts/admin-tails) ----
// GET: the table the old page rendered. Secrets never leave the server; only
// the last 4 characters, as the old table showed them.
$webhooks = [];
$baseCols = "id, slug, name, service, event_name, scope, target_username, verify_mode, secret, secret_header, enabled, last_received_at, received_count";
$result = false;
foreach ([$baseCols . ", last_attempt_at, last_status, last_error", $baseCols] as $cols) {
    try { $result = $conn->query("SELECT $cols FROM custom_webhooks ORDER BY name"); } catch (Throwable $e) { $result = false; }
    if ($result) break;
}
$adminKeys = wh_load_admin_keys($conn);
if ($result) {
    while ($wh = $result->fetch_assoc()) {
        $state = wh_key_state($wh, $adminKeys);
        $webhooks[] = [
            'id' => (int) $wh['id'], 'slug' => $wh['slug'], 'name' => $wh['name'], 'service' => $wh['service'],
            'event_name' => $wh['event_name'], 'scope' => $wh['scope'], 'target_username' => $wh['target_username'] ?? '',
            'verify_mode' => $wh['verify_mode'], 'secret_last4' => ($wh['verify_mode'] !== 'none' && !empty($wh['secret'])) ? substr($wh['secret'], -4) : '',
            'secret_header' => $wh['secret_header'], 'enabled' => (int) $wh['enabled'],
            'received_count' => (int) $wh['received_count'], 'last_received_at' => $wh['last_received_at'],
            'url' => $apiBase . '/webhook/' . $wh['slug'],
            'key_state' => $state, 'key_label' => $state ? t('admin_webhooks_key_' . $state) : null,
            'key_help' => $state ? t('admin_webhooks_key_' . $state . '_help', [$wh['service']]) : null,
            'last_status' => $wh['last_status'] ?? null, 'last_status_label' => !empty($wh['last_status']) ? wh_status_label($wh['last_status']) : null,
            'last_error' => $wh['last_error'] ?? null, 'last_attempt_at' => $wh['last_attempt_at'] ?? null,
        ];
    }
    $result->free();
}
wh_json(['success' => true, 'webhooks' => $webhooks, 'discord_log_event' => $discordLogEvent]);
